"""Preserve initial dirty bytes; archive only outputs generated by our test run."""
import hashlib,json,pathlib,subprocess,shutil,sys,datetime
R=pathlib.Path(__file__).resolve().parents[1];O=R/'docs/content/r12';B=R/'.audit-tmp/r12-protected'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def git(*a):return subprocess.check_output(['git',*a],cwd=R).decode('utf-8').split('\0')
if '--restore' not in sys.argv:
 O.mkdir(parents=True,exist_ok=True)
 rows={}
 for p in set(filter(None,git('diff','--name-only','-z')+git('ls-files','--others','--exclude-standard','-z'))):
  if p.startswith(('docs/content/r12/','.audit-tmp/')):continue
  f=R/p
  if not f.is_file():continue
  dest=B/p;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(f,dest);rows[p]=sha(f)
 tracked={p:sha(R/p) for p in filter(None,git('ls-files','-z')) if (R/p).is_file()}
 (O/'protected-start.json').write_text(json.dumps({'dirty':rows,'tracked':tracked},ensure_ascii=False,indent=2),encoding='utf-8')
 print('PREPARED protected',len(rows),'tracked',len(tracked))
else:
 data=json.loads((O/'protected-start.json').read_text(encoding='utf-8'));D=R/'.audit-tmp/r12-regression-outputs'/datetime.datetime.now().strftime('%Y%m%dT%H%M%S%f');restored=[]
 for p,h in {**data['tracked'],**data['dirty']}.items():
  historical=p in data['dirty'] or p.startswith(('docs/evidence/','docs/playtest/','docs/store/screenshots/','assets/generated/')) or p.startswith(tuple('docs/content/r'+str(i)+'/' for i in range(1,12)))
  if not historical:continue
  f=R/p
  if f.is_file() and sha(f)==h:continue
  assert not p.startswith(('assets/generated/content-r12/','docs/art/masters/content-r12/'))
  if f.is_file():
   dest=D/p;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(f,dest)
  f.parent.mkdir(parents=True,exist_ok=True)
  if p in data['dirty']:assert sha(B/p)==h;shutil.copyfile(B/p,f)
  else:f.write_bytes(subprocess.check_output(['git','show','HEAD:'+p],cwd=R))
  assert sha(f)==h;restored.append(p)
 assert all((R/p).is_file() and sha(R/p)==h for p,h in data['dirty'].items())
 (O/'protected-readback.json').write_text(json.dumps({'status':'VERIFIED','protected':len(data['dirty']),'restored':restored,'archive':D.relative_to(R).as_posix()},ensure_ascii=False,indent=2),encoding='utf-8')
 print('VERIFIED initial user bytes preserved; restored',len(restored))
